// Tu dong inject modals neu mo file truc tiep hoac client-side
(function() {
    var modalsHtml = "    <!-- ============================================================\n         PLACE DETAIL MODAL (#placeDetailModal)\n         Khi click vào địa điểm: Ảnh, Rating, Review, Giờ mở cửa, Giá, Hoạt động, Favorite\n         ============================================================ -->\n    <div class=\"modal fade\" id=\"placeDetailModal\" tabindex=\"-1\" aria-labelledby=\"placeDetailTitle\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n            <div class=\"modal-content clean-modal overflow-hidden\">\n                <div class=\"place-detail-hero\">\n                    <img id=\"pd-image\" src=\"\" alt=\"Hình ảnh địa điểm\" class=\"place-detail-img\" referrerpolicy=\"no-referrer\">\n                    <button type=\"button\" class=\"btn-close place-detail-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                    <div class=\"place-detail-badges\">\n                        <span id=\"pd-category\" class=\"pd-cat-pill\">Điểm đến</span>\n                        <span id=\"pd-rating\" class=\"pd-rating-pill\">★ 4.5</span>\n                    </div>\n                </div>\n\n                <div id=\"pd-gallery\" class=\"pd-gallery\"></div>\n\n                <div class=\"modal-body p-4\">\n                    <div class=\"d-flex align-items-start justify-content-between gap-3 mb-3\">\n                        <div>\n                            <h4 id=\"pd-title\" class=\"fw-bold mb-1\">Tên địa điểm</h4>\n                            <div id=\"pd-address\" class=\"small text-secondary\">\n                                <i class=\"fa-solid fa-location-dot text-primary me-1\"></i>\n                                <span>Hà Nội</span>\n                            </div>\n                        </div>\n                        <button type=\"button\" id=\"pd-fav-btn\" class=\"btn-pd-favorite\">\n                            ❤️ Yêu thích\n                        </button>\n                    </div>\n\n                    <!-- 3 Ô Thông số chính: Giờ mở cửa, Giá dự kiến, Thời gian dừng -->\n                    <div class=\"row g-2 mb-3\">\n                        <div class=\"col-12 col-sm-4\">\n                            <div class=\"pd-info-box\">\n                                <span class=\"pd-info-label\"><i class=\"fa-regular fa-clock text-primary me-1\"></i>Giờ mở cửa</span>\n                                <strong id=\"pd-hours\" class=\"pd-info-value\">08:00 – 21:00</strong>\n                                <small id=\"pd-hours-note\" class=\"pd-info-note\"></small>\n                            </div>\n                        </div>\n                        <div class=\"col-12 col-sm-4\">\n                            <div class=\"pd-info-box\">\n                                <span class=\"pd-info-label\"><i class=\"fa-solid fa-wallet text-primary me-1\"></i>Chi phí tham khảo</span>\n                                <strong id=\"pd-price\" class=\"pd-info-value\">50.000 đ</strong>\n                                <small id=\"pd-price-note\" class=\"pd-info-note\"></small>\n                            </div>\n                        </div>\n                        <div class=\"col-12 col-sm-4\">\n                            <div class=\"pd-info-box\">\n                                <span class=\"pd-info-label\"><i class=\"fa-solid fa-hourglass-half text-primary me-1\"></i>Khung giờ trong lịch</span>\n                                <strong id=\"pd-slot\" class=\"pd-info-value\">09:00 – 10:00</strong>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- Hoạt động & Trải nghiệm theo ngữ cảnh -->\n                    <div class=\"pd-section-block mb-3\">\n                        <div class=\"pd-section-label\">\n                            <i class=\"fa-solid fa-person-hiking text-primary me-1\"></i> Hoạt động & Trải nghiệm gợi ý\n                        </div>\n                        <p id=\"pd-activity\" class=\"mb-2 text-main fw-medium\"></p>\n                        <div id=\"pd-tags\" class=\"mb-2\"></div>\n                        <div id=\"pd-context-note\" class=\"s2-context-exp mb-0\"></div>\n                    </div>\n\n                    <!-- Đánh giá & Review thực tế -->\n                    <div class=\"pd-section-block\">\n                        <div class=\"pd-section-label\">\n                            <i class=\"fa-regular fa-comment-dots text-primary me-1\"></i> Đánh giá & Review thực tế\n                        </div>\n                        <div id=\"pd-insight\" class=\"small text-secondary mb-2\"></div>\n                        <blockquote id=\"pd-review\" class=\"pd-review-box mb-0\"></blockquote>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- ============================================================\n         MODALS PHỤC VỤ CRUD TRỰC TIẾP TRÊN SCREEN 3 (KHÔNG CẦN AI)\n         ============================================================ -->\n\n\n    <!-- 1. Modal ＋ Thêm Địa Điểm (#addPlaceModal) -->\n    <div class=\"modal fade\" id=\"addPlaceModal\" tabindex=\"-1\" aria-labelledby=\"addPlaceModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <div>\n                        <span class=\"section-eyebrow\">＋ Thêm điểm dừng</span>\n                        <h5 class=\"modal-title fw-bold\" id=\"addPlaceModalLabel\">Chọn địa điểm thêm vào lộ trình</h5>\n                    </div>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <input type=\"hidden\" id=\"add-place-after-id\" value=\"\">\n                    <div class=\"row g-2 mb-3\">\n                        <div class=\"col-12 col-sm-6\">\n                            <input type=\"text\" id=\"add-place-search\" class=\"form-control clean-input\" placeholder=\"Tìm theo tên địa điểm...\">\n                        </div>\n                        <div class=\"col-6 col-sm-3\">\n                            <select id=\"add-place-category\" class=\"form-select clean-input\">\n                                <option value=\"\">Tất cả loại hình</option>\n                                <option value=\"Cafe\">Cafe</option>\n                                <option value=\"Ăn uống\">Ăn uống</option>\n                                <option value=\"Tham quan\">Tham quan</option>\n                                <option value=\"Checkin\">Check-in</option>\n                                <option value=\"TTTM\">Rạp phim & TTTM</option>\n                            </select>\n                        </div>\n                        <div class=\"col-6 col-sm-3\">\n                            <div class=\"input-group\">\n                                <input type=\"number\" id=\"add-place-duration\" class=\"form-control clean-input\" value=\"45\" min=\"15\" max=\"240\" step=\"5\">\n                                <span class=\"input-group-text bg-light border-start-0 small\">phút</span>\n                            </div>\n                        </div>\n                    </div>\n                    <div id=\"add-place-candidates-list\" class=\"crud-candidates-list\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n    <!-- 2. Modal ↔ Thay Thế Địa Điểm (#replacePlaceModal) -->\n    <div class=\"modal fade\" id=\"replacePlaceModal\" tabindex=\"-1\" aria-labelledby=\"replacePlaceModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <div>\n                        <span class=\"section-eyebrow\">↔ Thay thế địa điểm</span>\n                        <h5 class=\"modal-title fw-bold\" id=\"replacePlaceModalLabel\">Đổi sang địa điểm tương đương</h5>\n                    </div>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <input type=\"hidden\" id=\"replace-old-place-id\" value=\"\">\n\n                    <!-- Target place summary banner -->\n                    <div id=\"replace-target-banner\" class=\"p-3 rounded-3 mb-3 d-flex flex-wrap align-items-center justify-content-between gap-2\" style=\"background: var(--bg-secondary); border: 1px solid var(--border-color);\">\n                        <div class=\"d-flex align-items-center gap-2\">\n                            <span class=\"badge bg-primary px-2 py-1\"><i class=\"fa-solid fa-location-dot me-1\"></i> Điểm cần đổi</span>\n                            <div>\n                                <span class=\"fw-bold text-main\" id=\"replace-old-place-name\"></span>\n                                <span class=\"badge bg-light text-dark border ms-2\" id=\"replace-old-place-cat\"></span>\n                            </div>\n                        </div>\n                        <div class=\"small text-secondary\" id=\"replace-old-place-meta\">\n                            <span id=\"replace-old-place-time\"><i class=\"fa-regular fa-clock me-1\"></i>45p</span>\n                            <span class=\"mx-1\">·</span>\n                            <span id=\"replace-old-place-slot\">08:00–08:45</span>\n                        </div>\n                    </div>\n\n                    <!-- Search & category filter chips -->\n                    <div class=\"row g-2 mb-3 align-items-center\">\n                        <div class=\"col-12 col-md-5\">\n                            <div class=\"input-group\">\n                                <span class=\"input-group-text bg-white border-end-0 text-secondary\"><i class=\"fa-solid fa-magnifying-glass\"></i></span>\n                                <input type=\"text\" id=\"replace-search-input\" class=\"form-control clean-input border-start-0 ps-0\" placeholder=\"Tìm theo tên địa điểm...\">\n                            </div>\n                        </div>\n                        <div class=\"col-12 col-md-7\">\n                            <div class=\"replace-category-chips d-flex gap-1 overflow-x-auto pb-1\" id=\"replace-category-chips\" style=\"white-space: nowrap;\">\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-primary active text-nowrap\" data-cat=\"same\">🎯 Cùng loại hình</button>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary text-nowrap\" data-cat=\"\">Tất cả</button>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary text-nowrap\" data-cat=\"Tham quan\">🏛️ Tham quan</button>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary text-nowrap\" data-cat=\"Ăn uống\">🍜 Ăn uống</button>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary text-nowrap\" data-cat=\"Cafe\">☕ Cafe</button>\n                                <button type=\"button\" class=\"btn btn-sm btn-outline-secondary text-nowrap\" data-cat=\"TTTM\">🛍️ TTTM</button>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div id=\"replace-context-tip\" class=\"small text-secondary mb-2\">\n                        <i class=\"fa-solid fa-circle-info text-primary me-1\"></i>\n                        <span id=\"replace-context-text\">Gợi ý các địa điểm cùng loại hình, gần lộ trình và đang mở cửa:</span>\n                    </div>\n\n                    <div id=\"replace-candidates-list\" class=\"crud-candidates-list\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n    <!-- 3. Modal ⏱ Đổi Thời Gian (#changeTimeModal) -->\n    <div class=\"modal fade\" id=\"changeTimeModal\" tabindex=\"-1\" aria-labelledby=\"changeTimeModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <div>\n                        <span class=\"section-eyebrow\">⏱ Điều chỉnh thời gian</span>\n                        <h5 class=\"modal-title fw-bold\" id=\"changeTimeModalLabel\">Cập nhật thời lượng & khung giờ</h5>\n                    </div>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <input type=\"hidden\" id=\"change-time-place-id\" value=\"\">\n                    <div id=\"change-time-place-box\" class=\"mb-3 p-3 rounded-3\" style=\"background: var(--bg-secondary);\">\n                        <label for=\"custom_visit_time_input\" class=\"field-label mb-1\">\n                            Thời gian dừng tại <strong id=\"change-time-place-name\" class=\"text-primary\"></strong> (phút):\n                        </label>\n                        <input type=\"number\" id=\"custom_visit_time_input\" class=\"form-control clean-input\" min=\"10\" max=\"360\" step=\"5\" value=\"60\">\n                    </div>\n\n                    <div class=\"row g-2 mb-4\">\n                        <div class=\"col-6\">\n                            <label for=\"modal_start_time\" class=\"field-label\">Giờ bắt đầu chuyến đi</label>\n                            <input type=\"time\" id=\"modal_start_time\" class=\"form-control clean-input\">\n                        </div>\n                        <div class=\"col-6\">\n                            <label for=\"modal_end_time\" class=\"field-label\">Giờ kết thúc dự kiến</label>\n                            <input type=\"time\" id=\"modal_end_time\" class=\"form-control clean-input\">\n                        </div>\n                    </div>\n\n                    <button type=\"button\" id=\"btn-confirm-change-time\" class=\"btn-primary-cta w-100 py-2\">\n                        Lưu & Tính lại giờ di chuyển\n                    </button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- ============================================================\n         MODALS: ACCOUNT (LOGIN & PROFILE) + ADMIN IMPORT\n         ============================================================ -->\n    <div class=\"modal fade\" id=\"loginModal\" tabindex=\"-1\" aria-labelledby=\"loginModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <h5 class=\"modal-title fw-bold\" id=\"loginModalLabel\">Đăng nhập Teravue</h5>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n\n                <div class=\"modal-body pt-3\">\n                    <p class=\"text-secondary small mb-4\">Lưu lại lịch trình yêu thích và đồng bộ dữ liệu tài khoản của bạn.</p>\n                    <form id=\"login-form\">\n                        <div class=\"mb-3\">\n                            <label for=\"login_email\" class=\"field-label\">Email tài khoản</label>\n                            <input type=\"email\" id=\"login_email\" class=\"form-control clean-input\" value=\"traveler@teravue.vn\" placeholder=\"ban@example.com\" required>\n                        </div>\n                        <div class=\"mb-4\">\n                            <label for=\"login_password\" class=\"field-label\">Mật khẩu</label>\n                            <input type=\"password\" id=\"login_password\" class=\"form-control clean-input\" value=\"123456\" placeholder=\"••••••••\">\n                        </div>\n                        <button type=\"submit\" id=\"btn-submit-login\" class=\"btn-primary-cta w-100 py-2\">\n                            <i class=\"fa-solid fa-right-to-bracket me-1\"></i> Đăng nhập\n                        </button>\n                    </form>\n                    <div id=\"login-feedback\" class=\"mt-2 text-center small fw-semibold\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"modal fade\" id=\"accountModal\" tabindex=\"-1\" aria-labelledby=\"accountModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <h5 class=\"modal-title fw-bold\" id=\"accountModalLabel\">Hồ sơ du lịch của bạn</h5>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <div class=\"d-flex align-items-center gap-3 mb-4 p-3 rounded-4\" style=\"background: var(--bg-secondary);\">\n                        <img src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=120&q=80\" alt=\"Avatar\" class=\"rounded-circle\" id=\"profile-avatar-img\" width=\"56\" height=\"56\">\n                        <div>\n                            <h6 class=\"fw-bold mb-0\" id=\"profile-display-name\">Du khách Hà Nội</h6>\n                            <div class=\"small text-secondary\" id=\"profile-display-email\">traveler@teravue.vn</div>\n                        </div>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"profile_name_input\" class=\"field-label\">Họ và tên</label>\n                        <input type=\"text\" id=\"profile_name_input\" class=\"form-control clean-input\" value=\"Du khách Hà Nội\">\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"profile_pref\" class=\"field-label\">Gu du lịch mặc định</label>\n                        <input type=\"text\" id=\"profile_pref\" class=\"form-control clean-input\" value=\"Yên tĩnh, thích cà phê cổ điển & di tích văn hóa\">\n                    </div>\n                    <button type=\"button\" id=\"btn-save-profile\" class=\"btn-primary-clean w-100 mt-2\">\n                        <i class=\"fa-solid fa-floppy-disk me-1\"></i> Lưu thông tin\n                    </button>\n                    <div id=\"profile-save-feedback\" class=\"mt-2 text-center small fw-semibold\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n    <!-- 4. Modal Danh Sách Yêu Thích (#favoritesModal) -->\n    <div class=\"modal fade\" id=\"favoritesModal\" tabindex=\"-1\" aria-labelledby=\"favoritesModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-0\">\n                    <div>\n                        <span class=\"section-eyebrow text-danger\"><i class=\"fa-solid fa-heart me-1\"></i> Bộ sưu tập cá nhân</span>\n                        <h5 class=\"modal-title fw-bold\" id=\"favoritesModalLabel\">Địa điểm yêu thích đã lưu</h5>\n                    </div>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <div id=\"favorites-list-container\" class=\"crud-candidates-list\" style=\"max-height: 480px; overflow-y: auto;\">\n                        <div class=\"text-center py-5 text-secondary\">\n                            <i class=\"fa-solid fa-spinner fa-spin fa-2x mb-2 text-primary\"></i>\n                            <div>Đang tải danh sách yêu thích...</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Nút ẩn Admin -->\n    <div class=\"admin-trigger d-none\" data-bs-toggle=\"modal\" data-bs-target=\"#adminModal\" title=\"Quản trị dữ liệu\">\n        <i class=\"fa-solid fa-gear\"></i>\n    </div>\n\n    <!-- Modal Admin Import Excel -->\n    <div class=\"modal fade\" id=\"adminModal\" tabindex=\"-1\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0\">\n                    <h5 class=\"modal-title fw-bold\">Admin: Import Dữ liệu Địa điểm</h5>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body\">\n                    <input type=\"file\" id=\"excel_file\" class=\"form-control clean-input mb-3\" accept=\".xlsx, .xls, .csv\">\n                    <button type=\"button\" id=\"btn-upload-excel\" class=\"btn-primary-clean w-100\">\n                        <i class=\"fa-solid fa-cloud-arrow-up me-1\"></i> Tải lên Database\n                    </button>\n                    <div id=\"upload-status\" class=\"mt-3 text-center fw-semibold\"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n\n    <!-- 5. Modal Xem & Tải ảnh Lịch trình (#imagePreviewModal) -->\n    <div class=\"modal fade\" id=\"imagePreviewModal\" tabindex=\"-1\" aria-labelledby=\"imagePreviewModalLabel\" aria-hidden=\"true\">\n        <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n            <div class=\"modal-content clean-modal\">\n                <div class=\"modal-header border-0 pb-1\">\n                    <div>\n                        <span class=\"section-eyebrow text-primary\"><i class=\"fa-solid fa-image me-1\"></i> Ảnh lịch trình chuyến đi</span>\n                        <h5 class=\"modal-title fw-bold\" id=\"imagePreviewModalLabel\">Bản lưu ảnh lộ trình du lịch</h5>\n                    </div>\n                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Đóng\"></button>\n                </div>\n                <div class=\"modal-body text-center p-3\">\n                    <div class=\"alert alert-success py-2 px-3 mb-3 d-flex align-items-center justify-content-between\" style=\"border-radius: 12px; font-size: 0.88rem;\">\n                        <span><i class=\"fa-solid fa-circle-check text-success me-2\"></i>Đã tạo ảnh lịch trình thành công!</span>\n                        <a href=\"#\" id=\"modal-btn-download-again\" class=\"btn btn-sm btn-success py-1 px-3\" style=\"border-radius: 8px;\">\n                            <i class=\"fa-solid fa-download me-1\"></i> Tải lại ảnh\n                        </a>\n                    </div>\n                    <div style=\"background: #F1F5F9; border-radius: 16px; padding: 12px; overflow-x: auto; max-height: 65vh;\">\n                        <img id=\"itinerary-preview-img\" src=\"\" alt=\"Lịch trình chi tiết\" class=\"img-fluid rounded shadow-sm\" style=\"max-height: 60vh; width: auto; display: block; margin: 0 auto;\">\n                    </div>\n                    <div class=\"small text-secondary mt-2\">\n                        <i class=\"fa-solid fa-mobile-screen-button me-1\"></i> <strong>Mẹo di động:</strong> Bạn có thể <em>nhấn giữ vào ảnh</em> trên màn hình điện thoại rồi chọn <strong>\"Lưu vào Ảnh\" (Save to Photos)</strong> để lưu ngay vào thư viện ảnh hoặc gửi qua Zalo/Facebook.\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n";
    function inject() {
        var container = document.getElementById('modals-container');
        if (container && !document.getElementById('placeDetailModal')) {
            container.innerHTML = modalsHtml;
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', inject);
    } else {
        inject();
    }
})();
